"use client";

import { CircleCheckIcon, InfoIcon, OctagonXIcon, TriangleAlertIcon } from "lucide-react";
import {
  type ExternalToast,
  toast as sonnerToast,
  Toaster as Sonner,
  type ToasterProps
} from "sonner";

import { useV4Theme } from "../scope";
import { Spinner } from "./spinner";

import styles from "./sonner.module.css";

export const V4_TOASTER_ID = "infisical-v4";

type Message = Parameters<typeof sonnerToast>[0];
const routed = (data?: ExternalToast): ExternalToast => ({
  ...data,
  toasterId: data?.toasterId ?? V4_TOASTER_ID
});

export const toast = Object.assign(
  (message: Message, data?: ExternalToast) => sonnerToast(message, routed(data)),
  {
    success: (message: Message, data?: ExternalToast) => sonnerToast.success(message, routed(data)),
    error: (message: Message, data?: ExternalToast) => sonnerToast.error(message, routed(data)),
    info: (message: Message, data?: ExternalToast) => sonnerToast.info(message, routed(data)),
    warning: (message: Message, data?: ExternalToast) => sonnerToast.warning(message, routed(data)),
    loading: (message: Message, data?: ExternalToast) => sonnerToast.loading(message, routed(data)),
    message: (message: Message, data?: ExternalToast) => sonnerToast.message(message, routed(data)),
    promise: <T,>(
      promise: Parameters<typeof sonnerToast.promise<T>>[0],
      data?: Parameters<typeof sonnerToast.promise<T>>[1]
    ) => sonnerToast.promise<T>(promise, { ...data, toasterId: data?.toasterId ?? V4_TOASTER_ID }),
    custom: (jsx: Parameters<typeof sonnerToast.custom>[0], data?: ExternalToast) =>
      sonnerToast.custom(jsx, routed(data)),
    dismiss: (id?: number | string) => {
      if (id !== undefined) return sonnerToast.dismiss(id);
      sonnerToast
        .getToasts()
        .filter((item) => "toasterId" in item && item.toasterId === V4_TOASTER_ID)
        .forEach((item) => sonnerToast.dismiss(item.id));
      return undefined;
    }
  }
);

const Toaster = ({ ...props }: ToasterProps) => {
  const resolvedTheme = useV4Theme();

  return (
    <Sonner
      theme={props.theme ?? resolvedTheme ?? "system"}
      className={styles.toaster}
      expand
      gap={8}
      icons={{
        success: <CircleCheckIcon className="size-4" />,
        info: <InfoIcon className="size-4" />,
        warning: <TriangleAlertIcon className="size-4" />,
        error: <OctagonXIcon className="size-4" />,
        loading: <Spinner />
      }}
      style={{ "--width": "min(400px, calc(100vw - 32px))" } as React.CSSProperties}
      toastOptions={{
        unstyled: true,
        classNames: {
          toast: styles.toast,
          icon: styles.icon,
          content: styles.content,
          title: styles.title,
          description: styles.description,
          actionButton: styles.action
        }
      }}
      {...props}
      id={props.id ?? V4_TOASTER_ID}
    />
  );
};

export { Toaster };

export { type ToastItem, ToastStack } from "./toast-stack";

.toaster[data-sonner-toaster] {
  font-family: var(--v4-type-row-title-font-family);
  color: var(--v4-toast-text);
}
.toast[data-sonner-toast] {
  width: var(--width);
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-8);
  padding: 12px;
  border: 1px solid var(--v4-toast-line);
  border-radius: calc(var(--v4-radius-card) * var(--corners));
  background: var(--v4-toast-bg);
  color: var(--v4-toast-text);
  box-shadow: var(--v4-shadow-pop);
}
.icon[data-icon] {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  position: relative;
  width: var(--v4-size-icon);
  height: var(--v4-type-row-title-line-height);
  color: var(--v4-toast-muted);
}
.icon[data-icon] svg {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
[data-type="success"] > .icon[data-icon] {
  color: var(--v4-toast-ok);
}
[data-type="error"] > .icon[data-icon] {
  color: var(--v4-toast-bad);
}
.content[data-content] {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.title[data-title] {
  font-family: var(--v4-type-row-title-font-family);
  font-size: var(--v4-type-row-title-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-row-title-font-weight);
  letter-spacing: var(--v4-type-row-title-letter-spacing);
}
.description[data-description] {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-toast-muted);
}
.action[data-button] {
  flex: none;
  margin-inline-start: auto;
  border: 0;
  padding: 0;
  background: none;
  cursor: pointer;
  color: var(--v4-accent-fg);
  font-family: var(--v4-type-row-title-font-family);
  font-size: var(--v4-type-row-title-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-row-title-font-weight);
}
